  (mkTbNocRouter_instance->INST_router.INST_routeWhere_0.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_routeWhere_1.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_routeWhere_2.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_routeWhere_3.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_routeWhere_4.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_pkt_dir_0.set_clk_0)("CLK");
