/* VCD dumping functions */
MOD_mkTbNocRouter & mkTbNocRouter_backing(tSimStateHdl simHdl)
{
  static MOD_mkTbNocRouter *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkTbNocRouter(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
void MODEL_mkTbNocRouter::dump_VCD_defs()
{
  (mkTbNocRouter_instance->dump_VCD_defs)(vcd_depth(sim_hdl));
}
void MODEL_mkTbNocRouter::dump_VCD(tVCDDumpType dt)
{
  (mkTbNocRouter_instance->dump_VCD)(dt, vcd_depth(sim_hdl), mkTbNocRouter_backing(sim_hdl));
}
